diff --git a/lib/src/cli/cli_dispatcher.dart b/lib/src/cli/cli_dispatcher.dart
index 18e5b9f..a10d736 100644
--- a/lib/src/cli/cli_dispatcher.dart
+++ b/lib/src/cli/cli_dispatcher.dart
@@ -274,7 +274,11 @@ Options:
       _writer('Error: invalid config JSON — ${e.message}');
       return 1;
     } on FileSystemException catch (e) {
-      _writer('Error: ${e.message}');
+      // e.message alone is just "Cannot open file" — without the path the
+      // leg logs give nothing actionable (live: dmtools-dart pr-301 review
+      // 2026-09-29, "Error: Cannot open file" with zero context).
+      _writer(
+          'Error: ${e.message} (path: ${e.path}, osError: ${e.osError?.message ?? 'n/a'})');
       return 1;
     } catch (e) {
       _writer('Error: $e');
diff --git a/test/cli/cli_dispatcher_test.dart b/test/cli/cli_dispatcher_test.dart
index 824980d..d26c23c 100644
--- a/test/cli/cli_dispatcher_test.dart
+++ b/test/cli/cli_dispatcher_test.dart
@@ -751,4 +751,28 @@ void _testDefaults() {
       );
     });
   });
+
+  group('run: FileSystemException carries the path', () {
+    // Regression: the handler printed only e.message — "Cannot open file" —
+    // which made factory leg logs undiagnosable (live: epam/dmtools-dart
+    // pr-301 review, run 36614989141, zero context for hours).
+    test('run on an unreadable config reports the offending path', () async {
+      final sealed = File('${_tmp.path}/sealed.json')
+        ..writeAsStringSync('{"name":"x"}');
+      // chmod 000 — File.open fails with FileSystemException("Cannot open
+      // file") on every supported platform except when running as root.
+      final failed = Process.runSync('chmod', ['000', sealed.path]);
+      if (failed.exitCode != 0) return; // root or non-POSIX: nothing to test
+      final code = await _dispatcher.dispatch(['run', sealed.path]);
+      expect(code, 1);
+      final errorLine = _lines.firstWhere(
+        (l) => l.startsWith('Error:'),
+        orElse: () => '<no error line>',
+      );
+      expect(errorLine, contains('Cannot open file'));
+      expect(errorLine, contains('(path: ${sealed.path}'));
+      Process.runSync('chmod', ['644', sealed.path]);
+      sealed.deleteSync();
+    });
+  });
 }

{
  "key": "pr-303",
  "fields": {
    "summary": "fix(cli): FileSystemException handler reports the file path",
    "description": "## Problem

`dmtools run` on a failing factory leg printed exactly one line: `Error: Cannot open file` (live: run 36614989141 — pr-301 review died like that for hours, undiagnosable). The `on FileSystemException` handler in [CliDispatcher] printed only `e.message` — for a failed `File.open` that message is literally "Cannot open file"; the path lives in `e.path` and was discarded.

## Fix

- Include `e.path` and `e.osError?.message` in the handler output.
- Regression test: an unreadable (chmod 000) config must produce an error line containing the path.

## Why it matters

The dmtools-dart factory legs die at this exact spot; with the path visible the next failure names the file instead of hiding it."
  }
}

