          'A comprehensive development management toolkit'
        ],
      );
    });

    test('-v alias matches', () async {
      expect(await _dispatcher.dispatch(['-v']), 0);
      expect(_lines.first, 'DMTools $dmtoolsVersion');
    });
  });
}

void _testHelp() {
  group('--help', () {
