/// [ToolBridge]. Interactive mode remains a stub pending Phase 4.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import '../agents/agent_factory.dart';
import '../agents/cli_agent.dart';
import '../agents/teammate_job.dart';
