  _testDirectTool();
  _testDirectToolNamedArgs();
  _testDirectToolNamedArgsPrecedence();
  _testDirectToolJavaArgs();
  _testDirectToolJavaArgForms();
  _testDirectToolJavaFlags();
  _testDirectToolJavaFlagStripping();
  _testDirectToolJavaDataFlags();
  _testDirectToolHelp();
  _testNoArgs();
  _testDefaults();
}

void _testVersion() {
  group('--version', () {
