    final jsPath = params['jsPath'] as String?;
    if (jsPath == null || jsPath.trim().isEmpty) {
      // Java: IllegalArgumentException("jsPath parameter is required").
      return {'success': false, 'error': 'jsPath parameter is required'};
    }
