        scriptPath: jsPath,
        jobParams: _parseJobParams(params['jobParams']),
        ticket: _asMap(params['ticket']),
        config: JsRunConfig(contextParams: _contextParams()),
      );
      return {'success': true, 'result': result};
    } catch (e) {
      return {'success': false, 'error': e.toString()};
    }
  }

